#!/usr/bin/env python3
from __future__ import annotations

import subprocess
import sys
from pathlib import Path

REPO = Path("/Users/troynezki/Documents/GitHub/algebra")
BUILDER = '#!/usr/bin/env python3\n\nfrom __future__ import annotations\n\nimport csv\nimport html\nimport io\nimport re\nimport tempfile\nfrom datetime import date, datetime\nfrom pathlib import Path\n\nimport requests\nfrom openpyxl import load_workbook\n\nSPREADSHEET_ID = "1Qga2eTz0Nfgu8wIw5L-ZGC2xRtb4fOUoUXN-TyxuASE"\nSHEET_ID = "2143927343"\nSHEET_NAME = "Student Calendar"\n\nXLSX_URL = f"https://docs.google.com/spreadsheets/d/{SPREADSHEET_ID}/export?format=xlsx"\nVALUES_URL = (\n    f"https://docs.google.com/spreadsheets/d/{SPREADSHEET_ID}/gviz/tq"\n    f"?tqx=out:csv&gid={SHEET_ID}&range=A1:E500"\n)\n\nHERE = Path(__file__).resolve().parent\nOUTPUT = HERE / "index.html"\n\nRESOURCE_LINKS = [\n    ("Course Website", "https://tnezki.github.io/algebra/"),\n    ("Overview", "https://tnezki.github.io/algebra/misc/overview.html"),\n    ("Textbook", "https://tnezki.github.io/textbooks/alg/index.html"),\n    ("Virtual Tools", "https://technology.cpm.org/general/tiles/"),\n    ("Printables", "https://tnezki.github.io/algebra/misc/printables/aaagallery_index.html"),\n    ("Desmos", "https://www.desmos.com/calculator"),\n    ("GeoGebra", "https://www.geogebra.org/graphing"),\n    ("Canvas", "https://mariners.instructure.com/"),\n    (\n        "Upload Spot",\n        "https://drive.google.com/drive/folders/1DwDKsvsAHMFefLMderdK8PI3MBcvXAxu?usp=sharing",\n    ),\n]\n\nDAY_NAMES = ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday"]\n\n\ndef get(url: str) -> requests.Response:\n    response = requests.get(\n        url,\n        timeout=45,\n        headers={"User-Agent": "Mozilla/5.0 AgendaBuilder/2.0"},\n    )\n    response.raise_for_status()\n    return response\n\n\ndef download_display_values():\n    """Get Google\'s evaluated/formatted Student Calendar values as CSV."""\n    response = get(VALUES_URL)\n    rows = list(csv.reader(io.StringIO(response.text)))\n\n    # Normalize to at least 500 rows x 5 cols so coordinate reads are safe.\n    normalized = []\n    for row in rows:\n        normalized.append((row + [""] * 5)[:5])\n    while len(normalized) < 500:\n        normalized.append([""] * 5)\n    return normalized\n\n\ndef download_xlsx():\n    """XLSX is used only to recover hyperlink targets."""\n    response = get(XLSX_URL)\n    if len(response.content) < 1000:\n        raise RuntimeError("Google returned an unexpectedly small workbook export.")\n\n    temp = tempfile.NamedTemporaryFile(suffix=".xlsx", delete=False)\n    temp.write(response.content)\n    temp.close()\n    return Path(temp.name)\n\n\ndef value_at(values, row: int, col: int) -> str:\n    try:\n        return str(values[row - 1][col - 1]).strip()\n    except (IndexError, TypeError):\n        return ""\n\n\ndef hyperlink_at(ws, row: int, col: int):\n    cell = ws.cell(row=row, column=col)\n\n    if cell.hyperlink and cell.hyperlink.target:\n        return cell.hyperlink.target\n\n    # Some exports retain HYPERLINK() rather than a hyperlink relationship.\n    raw = cell.value\n    if isinstance(raw, str) and raw.startswith("="):\n        match = re.search(r\'HYPERLINK\\(\\s*"([^"]+)"\', raw, re.I)\n        if match:\n            return match.group(1)\n\n    return None\n\n\ndef looks_like_date(value: str) -> bool:\n    return bool(re.fullmatch(r"\\d{1,2}/\\d{1,2}(?:/\\d{2,4})?", value.strip()))\n\n\ndef date_key(value: str, school_start_year=2026):\n    value = value.strip()\n    match = re.fullmatch(r"(\\d{1,2})/(\\d{1,2})(?:/(\\d{2,4}))?", value)\n    if not match:\n        return None\n\n    month = int(match.group(1))\n    day = int(match.group(2))\n    year_text = match.group(3)\n\n    if year_text:\n        year = int(year_text)\n        if year < 100:\n            year += 2000\n    else:\n        year = school_start_year if month >= 7 else school_start_year + 1\n\n    try:\n        return date(year, month, day)\n    except ValueError:\n        return None\n\n\ndef gather_items(values, ws_links, start_row: int, end_row: int, col: int):\n    items = []\n    for row in range(start_row, end_row + 1):\n        label = value_at(values, row, col)\n        if not label:\n            continue\n        items.append((label, hyperlink_at(ws_links, row, col)))\n    return items\n\n\ndef read_calendar():\n    values = download_display_values()\n    xlsx = download_xlsx()\n\n    try:\n        workbook = load_workbook(xlsx, data_only=False, read_only=False)\n\n        if SHEET_NAME not in workbook.sheetnames:\n            raise RuntimeError(f"Missing sheet: {SHEET_NAME}")\n\n        ws_links = workbook[SHEET_NAME]\n\n        # The current week is always the special block at the top.\n        current_dates = [value_at(values, 2, c) for c in range(1, 6)]\n        current_items = [\n            gather_items(values, ws_links, 3, 9, c)\n            for c in range(1, 6)\n        ]\n\n        current_start = next(\n            (date_key(x) for x in current_dates if date_key(x)),\n            None,\n        )\n\n        # Previous weeks have date rows farther down the Student Calendar.\n        archive_date_rows = []\n        for row in range(11, 501):\n            row_values = [value_at(values, row, c) for c in range(1, 6)]\n            if sum(1 for v in row_values if looks_like_date(v)) >= 4:\n                archive_date_rows.append(row)\n\n        previous = []\n        for i, date_row in enumerate(archive_date_rows):\n            next_date_row = (\n                archive_date_rows[i + 1]\n                if i + 1 < len(archive_date_rows)\n                else min(date_row + 11, 501)\n            )\n\n            dates = [value_at(values, date_row, c) for c in range(1, 6)]\n            start = next((date_key(x) for x in dates if date_key(x)), None)\n\n            # Don\'t duplicate the special current-week block.\n            if current_start and start and start >= current_start:\n                continue\n\n            content_end = min(next_date_row - 1, date_row + 10)\n            items = [\n                gather_items(values, ws_links, date_row + 1, content_end, c)\n                for c in range(1, 6)\n            ]\n\n            if any(items):\n                previous.append({"dates": dates, "items": items})\n\n        return {\n            "current": {"dates": current_dates, "items": current_items},\n            "previous": previous,\n        }\n    finally:\n        try:\n            xlsx.unlink()\n        except OSError:\n            pass\n\n\ndef render_link(label: str, url: str | None, kind: str = "") -> str:\n    classes = "cal-link" + (f" {kind}" if kind else "")\n    safe_label = html.escape(label)\n\n    if url:\n        return (\n            f\'<a class="{classes}" href="{html.escape(url, quote=True)}" \'\n            f\'target="_blank" rel="noopener">{safe_label}</a>\'\n        )\n\n    return f\'<span class="{classes} no-link">{safe_label}</span>\'\n\n\ndef render_week(dates, items_by_day, current=False):\n    if current:\n        weekday_cells = "".join(\n            f"<th><div class=\'dow\'>{day}</div></th>"\n            for day in DAY_NAMES\n        )\n        date_cells = "".join(\n            f"<th><div class=\'date\'>{html.escape(d)}</div></th>"\n            for d in dates\n        )\n        header = (\n            f\'<tr class="week-head">{weekday_cells}</tr>\'\n            f\'<tr class="current-date-row">{date_cells}</tr>\'\n        )\n        block_class = "current-week"\n    else:\n        cells = "".join(\n            f"<th><div class=\'dow\'>{day}</div>"\n            f"<div class=\'date\'>{html.escape(d)}</div></th>"\n            for day, d in zip(DAY_NAMES, dates)\n        )\n        header = f\'<tr class="week-head">{cells}</tr>\'\n        block_class = "previous-week"\n\n    max_items = max([len(items) for items in items_by_day] + [1])\n    rows = []\n\n    for item_index in range(max_items):\n        cells = []\n        for items in items_by_day:\n            if item_index >= len(items):\n                cells.append("<td></td>")\n                continue\n\n            label, url = items[item_index]\n\n            kind = ""\n            if item_index == 0:\n                lower = label.lower()\n                if any(\n                    phrase in lower\n                    for phrase in ("labor day", "pd", "no school", "holiday")\n                ):\n                    kind = "holiday"\n                else:\n                    kind = "lesson"\n\n            cells.append(f"<td>{render_link(label, url, kind)}</td>")\n\n        rows.append("<tr>" + "".join(cells) + "</tr>")\n\n    return (\n        f\'<tbody class="week-block {block_class}">\'\n        + header\n        + "".join(rows)\n        + "</tbody>"\n    )\n\n\ndef build_html(calendar):\n    resources = "\\n".join(\n        f\'<a href="{html.escape(url, quote=True)}" \'\n        f\'target="_blank" rel="noopener">{html.escape(label)}</a>\'\n        for label, url in RESOURCE_LINKS\n    )\n\n    current_html = render_week(\n        calendar["current"]["dates"],\n        calendar["current"]["items"],\n        current=True,\n    )\n\n    previous_html = ""\n    if calendar["previous"]:\n        previous_html = (\n            \'<tbody class="previous-weeks-divider">\'\n            \'<tr><td colspan="5">Previous Weeks</td></tr>\'\n            \'</tbody>\'\n            + "".join(\n                render_week(week["dates"], week["items"], current=False)\n                for week in calendar["previous"]\n            )\n        )\n\n    stamp = datetime.now().strftime("%Y-%m-%d %H:%M")\n\n    return f"""<!doctype html>\n<html lang="en">\n<head>\n<meta charset="utf-8">\n<meta name="viewport" content="width=device-width, initial-scale=1">\n<meta http-equiv="refresh" content="300">\n<title>Algebra 1 Agenda 2026-2027</title>\n<style>\n:root {{\n  --navy:#173f6d;\n  --navy-dark:#0f2f52;\n  --gold:#d9b84f;\n  --ink:#1f2937;\n  --muted:#64748b;\n  --lesson:#fff4c7;\n  --link:#173f6d;\n}}\n* {{ box-sizing:border-box; }}\nbody {{\n  margin:0;\n  font-family:Arial, Helvetica, sans-serif;\n  background:#fff;\n  color:var(--ink);\n}}\n.wrapper {{\n  width:min(1180px, calc(100% - 24px));\n  margin:18px auto 40px;\n}}\n.titlebar {{\n  background:var(--navy);\n  color:#fff;\n  padding:16px 22px;\n  border-radius:10px 10px 0 0;\n  text-align:center;\n}}\n.titlebar h1 {{\n  margin:0;\n  font-size:clamp(1.55rem, 3vw, 2.25rem);\n  font-weight:800;\n}}\n.titlebar .small {{\n  font-size:.64em;\n  font-weight:600;\n}}\n.resources {{\n  border:1px solid #c8b675;\n  border-top:0;\n  padding:12px 14px 13px;\n  display:flex;\n  flex-wrap:wrap;\n  justify-content:center;\n  gap:8px;\n  background:#f8f3df;\n}}\n.resources a {{\n  text-decoration:none;\n  color:var(--navy-dark);\n  background:#fff;\n  border:1px solid #c9ad52;\n  border-radius:999px;\n  padding:7px 11px;\n  font-size:.88rem;\n  font-weight:700;\n}}\n.resources a:hover,\n.resources a:focus-visible {{\n  background:var(--lesson);\n  border-color:var(--navy);\n}}\n.calendar-wrap {{\n  overflow-x:auto;\n  border:1px solid #c8b675;\n  border-top:0;\n}}\ntable {{\n  border-collapse:collapse;\n  width:100%;\n  min-width:760px;\n  table-layout:fixed;\n}}\nth, td {{\n  border-right:1px solid #cfd4da;\n  border-bottom:1px solid #cfd4da;\n  text-align:center;\n  vertical-align:middle;\n}}\ntr > *:last-child {{ border-right:0; }}\n.week-head th {{ padding:8px 6px; }}\n.dow {{ font-size:.9rem; font-weight:800; }}\n.date {{ margin-top:2px; font-size:.82rem; font-weight:700; }}\ntd {{ padding:5px 6px; background:#fff; height:34px; }}\n.cal-link {{\n  display:block;\n  width:100%;\n  text-decoration:none;\n  color:var(--link);\n  font-size:.88rem;\n  font-weight:650;\n  padding:4px 5px;\n  border-radius:5px;\n}}\na.cal-link:hover,\na.cal-link:focus-visible {{\n  background:#fff4c7;\n  text-decoration:underline;\n}}\n.cal-link.lesson {{\n  background:var(--lesson);\n  border:1px solid #e1c86d;\n  font-weight:800;\n  color:var(--navy-dark);\n}}\n.cal-link.holiday {{\n  background:#f6edcf;\n  color:#475569;\n  font-weight:800;\n}}\n.no-link {{ cursor:default; }}\n\n.current-week .week-head th {{\n  background:var(--navy-dark);\n  color:#fff;\n}}\n.current-week .current-date-row th {{\n  background:var(--gold);\n  color:#10243d;\n  padding:7px 6px;\n  font-weight:850;\n}}\n.current-week .current-date-row .date {{ font-size:.95rem; }}\n.current-week tr:nth-child(even) td {{ background:#fffaf0; }}\n\n.previous-weeks-divider td {{\n  background:#d9b84f !important;\n  color:#10243d;\n  font-size:1.05rem;\n  font-weight:800;\n  padding:10px 8px;\n}}\n\n.previous-week .week-head th {{\n  background:#3f4650;\n  color:#fff;\n  border-top:5px solid #20242a;\n}}\n.previous-week .week-head th .date {{ color:#e5e7eb; }}\n.previous-week tr td {{\n  background:#fff !important;\n  border-color:#cfd4da;\n}}\n.previous-week tr:nth-child(even) td {{\n  background:#f3f4f6 !important;\n}}\n.previous-week .cal-link.lesson {{\n  background:#e5e7eb;\n  border:1px solid #c7ccd1;\n  color:#2f3740;\n}}\n.previous-week .cal-link.holiday {{\n  background:#eceff2;\n  color:#4b5563;\n}}\n.previous-week a.cal-link:hover,\n.previous-week a.cal-link:focus-visible {{\n  background:#e2e6ea;\n}}\n.updated {{\n  text-align:center;\n  color:var(--muted);\n  font-size:.76rem;\n  padding-top:8px;\n}}\n\n@media (max-width:700px) {{\n  .wrapper {{ width:100%; margin:0; }}\n  .titlebar {{ border-radius:0; }}\n  .resources {{ justify-content:flex-start; padding:10px; }}\n  .resources a {{ font-size:.8rem; padding:6px 9px; }}\n}}\n</style>\n</head>\n<body>\n<div class="wrapper">\n  <header class="titlebar">\n    <h1>Algebra 1 <span class="small">– Agenda 2026-2027</span></h1>\n  </header>\n\n  <nav class="resources" aria-label="Student resources">\n    {resources}\n  </nav>\n\n  <div class="calendar-wrap">\n    <table aria-label="Algebra 1 student agenda">\n      {current_html}\n      {previous_html}\n    </table>\n  </div>\n\n  <div class="updated">Agenda generated {html.escape(stamp)}</div>\n</div>\n</body>\n</html>\n"""\n\n\ndef main():\n    calendar = read_calendar()\n    output = build_html(calendar)\n\n    # Replace the public page only after all Google reads and rendering succeed.\n    temp_output = OUTPUT.with_suffix(".html.tmp")\n    temp_output.write_text(output, encoding="utf-8")\n    temp_output.replace(OUTPUT)\n\n    print(f"Updated {OUTPUT}")\n\n\nif __name__ == "__main__":\n    main()\n'


def run(*args):
    print("$ " + " ".join(str(x) for x in args))
    subprocess.check_call([str(x) for x in args], cwd=str(REPO))


def main():
    if not REPO.exists():
        raise SystemExit(f"Algebra repo not found: {REPO}")

    # Get the automatic commit GitHub Actions made after the first test.
    run("git", "pull", "--ff-only", "origin", "main")

    builder_path = REPO / "agenda" / "build_agenda.py"
    builder_path.parent.mkdir(parents=True, exist_ok=True)
    builder_path.write_text(BUILDER, encoding="utf-8")
    print(f"Wrote fixed builder: {builder_path}")

    # Build locally first. If the Google reads fail, nothing gets committed.
    run(sys.executable, str(builder_path))

    run("git", "add", "agenda/build_agenda.py", "agenda/index.html")

    changed = subprocess.run(
        ["git", "diff", "--cached", "--quiet"],
        cwd=str(REPO),
    ).returncode != 0

    if changed:
        run("git", "commit", "-m", "Fix agenda formula rendering")
        run("git", "push", "origin", "main")
        print()
        print("FIX COMPLETE — builder and corrected agenda pushed to GitHub.")
    else:
        print()
        print("No changes needed.")


if __name__ == "__main__":
    main()
